// ============================================================
// EXTRACT FILES  (rewritten)
// n8n's Form Trigger stores uploaded files in the item's BINARY
// store, not in json['Field Label'].  The old version only looked
// at json, so p2_content / p3_content were always empty strings and
// the AI had nothing real to work with.
// ============================================================

const helpers = this.helpers;
const item = $input.first();
const form = item.json || {};
const binary = item.binary || {};

const category = form['Product Category'] || form.category || 'Area Rug';
const focus = form['Focus Area'] || form.focus || '';

// ---- locate the two binary properties, whatever n8n named them ----
const binKeys = Object.keys(binary);
const norm = (s) => String(s).toLowerCase().replace(/[^a-z0-9]/g, '');

function findKey(hints, exclude) {
  for (const h of hints) {
    const hn = norm(h);
    const hit = binKeys.find(k => k !== exclude && norm(k).includes(hn));
    if (hit) return hit;
  }
  return null;
}

let p2Key = findKey(['P2 Market Analysis Report', 'p2market', 'marketanalysis', 'trend', 'p2']);
let p3Key = findKey(['P3 Competitor Analysis Report', 'p3competitor', 'competitoranalysis', 'competitor', 'p3'], p2Key);

// positional fallback (n8n sometimes names them data / data_1)
if (!p2Key && binKeys.length > 0) p2Key = binKeys[0];
if (!p3Key) p3Key = binKeys.find(k => k !== p2Key) || null;

async function readBinary(propName) {
  if (!propName) return '';
  // preferred path — works with both in-memory and filesystem binary storage
  try {
    const buf = await helpers.getBinaryDataBuffer(0, propName);
    if (buf) return buf.toString('utf8');
  } catch (e) { /* fall through */ }
  // fallback — base64 held directly on the item
  const b = binary[propName];
  if (b && b.data) {
    try { return Buffer.from(b.data, 'base64').toString('utf8'); } catch (e) { /* noop */ }
  }
  return '';
}

let p2Raw = await readBinary(p2Key);
let p3Raw = await readBinary(p3Key);

// last-resort: some setups DO pass the file through json as a string
if (!p2Raw && typeof form['P2 Market Analysis Report'] === 'string') p2Raw = form['P2 Market Analysis Report'];
if (!p3Raw && typeof form['P3 Competitor Analysis Report'] === 'string') p3Raw = form['P3 Competitor Analysis Report'];

// ---- HTML -> readable text, keeping headings and list structure ----
const htmlToText = (html) => {
  if (!html) return '';
  return String(html)
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<head[\s\S]*?<\/head>/gi, ' ')
    .replace(/<h([1-6])[^>]*>/gi, '\n\n## ')
    .replace(/<li[^>]*>/gi, '\n- ')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/(h[1-6]|p|div|section|tr|li|ul|ol|table)>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/[ \t]{2,}/g, ' ')
    .replace(/\n[ \t]+/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
};

// ---- pull out concrete numbers so the AI can cite real figures ----
const extractStats = (t) => {
  const pcts = (t.match(/\b\d{1,3}(?:\.\d+)?\s?%/g) || []);
  const prices = (t.match(/\$\s?\d[\d,]*(?:\.\d{2})?(?:\s?[-\u2013to]+\s?\$?\d[\d,]*(?:\.\d{2})?)?/g) || []);
  const ratings = (t.match(/\b[1-5]\.\d\s?(?:stars?|\/\s?5)/gi) || []);
  const uniq = (a) => Array.from(new Set(a.map(s => s.trim())));
  return {
    percentages: uniq(pcts).slice(0, 30),
    prices: uniq(prices).slice(0, 30),
    ratings: uniq(ratings).slice(0, 10)
  };
};

const p2Text = htmlToText(p2Raw).slice(0, 14000);
const p3Text = htmlToText(p3Raw).slice(0, 14000);

const p2Stats = extractStats(p2Text);
const p3Stats = extractStats(p3Text);

// ---- honest reporting of what actually made it through ----
const missing = [];
if (p2Text.length < 200) missing.push('P2 Market / Trend Analysis');
if (p3Text.length < 200) missing.push('P3 Competitor Analysis');

const source_status = {
  p2_chars: p2Text.length,
  p3_chars: p3Text.length,
  p2_binary_key: p2Key,
  p3_binary_key: p3Key,
  binary_keys_seen: binKeys,
  missing: missing,
  ok: missing.length === 0
};

return [{
  json: {
    category,
    focus,
    p2_content: p2Text,
    p3_content: p3Text,
    p2_stats: p2Stats,
    p3_stats: p3Stats,
    source_status
  }
}];

