// ============================================================
// COLLECT SECTIONS  (replaces "Parse Content")
// Reads the four section agents, parses each independently, and
// repairs a truncated JSON object rather than throwing the whole
// report away.  A failure in one section no longer wipes out the
// other three.
// ============================================================

const src = $('Extract Files').first().json;

function tryParse(s) {
  try { return JSON.parse(s); } catch (e) { return null; }
}

// Walks the string tracking string-literal state so braces inside
// quoted text don't confuse the depth counter.
function extractJson(raw) {
  if (!raw) return null;
  let s = String(raw).replace(/```json/gi, '').replace(/```/g, '').trim();

  const start = s.indexOf('{');
  if (start === -1) return null;
  s = s.slice(start);

  // pass 1 — find a properly balanced object
  let depth = 0, inStr = false, esc = false, end = -1;
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    if (esc) { esc = false; continue; }
    if (ch === '\\') { esc = true; continue; }
    if (ch === '"') { inStr = !inStr; continue; }
    if (inStr) continue;
    if (ch === '{' || ch === '[') depth++;
    else if (ch === '}' || ch === ']') {
      depth--;
      if (depth === 0) { end = i; break; }
    }
  }
  if (end !== -1) {
    const parsed = tryParse(s.slice(0, end + 1));
    if (parsed) return parsed;
  }

  // pass 2 — output was truncated. Cut back to the last safe comma
  // at shallow depth, then close whatever is still open.
  const cuts = [];
  let st = [], is = false, es = false;
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    if (es) { es = false; continue; }
    if (ch === '\\') { es = true; continue; }
    if (ch === '"') { is = !is; continue; }
    if (is) continue;
    if (ch === '{' || ch === '[') st.push(ch);
    else if (ch === '}' || ch === ']') st.pop();
    else if (ch === ',' && st.length <= 3) cuts.push(i);
  }
  cuts.push(s.length);

  for (let n = cuts.length - 1; n >= 0 && n >= cuts.length - 40; n--) {
    let frag = s.slice(0, cuts[n]);
    let stack = [], inS = false, e2 = false;
    for (let i = 0; i < frag.length; i++) {
      const c = frag[i];
      if (e2) { e2 = false; continue; }
      if (c === '\\') { e2 = true; continue; }
      if (c === '"') { inS = !inS; continue; }
      if (inS) continue;
      if (c === '{' || c === '[') stack.push(c);
      else if (c === '}' || c === ']') stack.pop();
    }
    if (inS) frag += '"';
    frag = frag.replace(/[,\s]+$/, '');
    frag = frag.replace(/:\s*$/, ': null');
    while (stack.length) frag += (stack.pop() === '{' ? '}' : ']');
    const parsed = tryParse(frag);
    if (parsed) return parsed;
  }
  return null;
}

function readAgent(nodeName) {
  try {
    const j = $(nodeName).first().json;
    const raw = j.output || j.text || j.response || '';
    return extractJson(raw);
  } catch (e) {
    return null;
  }
}

const foundation = readAgent('Foundation Generator') || {};
const contentSocial = readAgent('Content & Social Generator') || {};
const campaignsEmail = readAgent('Campaigns & Email Generator') || {};
const competitive = readAgent('Competitive & Priorities Generator') || {};

// Assemble. Missing pieces stay empty — we surface that honestly in the
// report instead of silently substituting invented placeholder data.
const content = {
  key_metrics: foundation.key_metrics || [],
  data_foundation: foundation.data_foundation || { p2_insights: [], p3_insights: [] },
  executive_summary: foundation.executive_summary || '',
  content_ideas: contentSocial.content_ideas || [],
  social_captions: contentSocial.social_captions || {},
  campaigns: campaignsEmail.campaigns || [],
  email_subjects: campaignsEmail.email_subjects || [],
  competitive_angles: competitive.competitive_angles || [],
  content_priorities: competitive.content_priorities || []
};

const incomplete = [];
if (!content.executive_summary) incomplete.push('Executive Summary');
if (!content.key_metrics.length) incomplete.push('Key Metrics');
if (!content.content_ideas.length) incomplete.push('Content Ideas');
if (!Object.keys(content.social_captions).length) incomplete.push('Social Captions');
if (!content.campaigns.length) incomplete.push('Campaign Concepts');
if (!content.email_subjects.length) incomplete.push('Email Subject Lines');
if (!content.competitive_angles.length) incomplete.push('Competitive Angles');
if (!content.content_priorities.length) incomplete.push('Content Priorities');

return [{
  json: {
    content,
    category: src.category,
    focus: src.focus,
    source_status: src.source_status,
    incomplete_sections: incomplete
  }
}];

// ============================================================
// BUILD HTML  (rewritten)
// Fixes: grid tracks that couldn't shrink (clipped cards), flex rows
// that pushed badges off-screen, no word wrapping on long strings,
// no print/PDF rules (cards were sliced across page breaks).
// Adds: contents nav, data-quality banner, Wayfair-voice section copy.
// ============================================================

const data = $input.first().json;
const c = data.content || {};
const category = data.category || 'Area Rug';
const focus = data.focus || '';
const status = data.source_status || {};
const incomplete = data.incomplete_sections || [];
const today = new Date().toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' });

const esc = s => String(s === null || s === undefined ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const has = a => Array.isArray(a) && a.length > 0;

// friendly note shown when a section didn't come back from the model
const emptyNote = (what) => `<div class="empty-note">We weren't able to generate the ${esc(what)} section this run. Re-running the workflow usually resolves it — everything else below is complete.</div>`;

// ---------- Key metrics ----------
const metrics = c.key_metrics || [];
const metricsHtml = has(metrics) ? metrics.map(m => `
  <div class="insight-card">
    <div class="number">${esc(m.value)}</div>
    <div class="label">${esc(m.label)}</div>
    ${m.source ? `<div class="src">from ${esc(m.source)}</div>` : ''}
  </div>`).join('') : '';

// ---------- Data foundation ----------
const df = c.data_foundation || {};
const p2List = (df.p2_insights || []).map(i => `<li>${esc(i)}</li>`).join('');
const p3List = (df.p3_insights || []).map(i => `<li>${esc(i)}</li>`).join('');

// ---------- Content ideas ----------
const ideas = c.content_ideas || [];
const ideasHtml = ideas.map(i => {
  const kws = (i.seo_keywords || []).map(k => `<span class="keyword">${esc(k)}</span>`).join('');
  return `
  <article class="content-card">
    <div class="content-card-header">
      <div class="type">${esc(i.type)}</div>
      <h4>${esc(i.title)}</h4>
    </div>
    <div class="content-card-body">
      <p>${esc(i.description)}</p>
      ${i.data_connection ? `<div class="data-tag"><span aria-hidden="true">&#128202;</span> ${esc(i.data_connection)}</div>` : ''}
      ${kws ? `<div class="keywords">${kws}</div>` : ''}
    </div>
  </article>`;
}).join('');

// ---------- Social captions ----------
const soc = c.social_captions || {};
const igHtml = (soc.instagram || []).map(p => `
  <div class="social-post">
    <div class="platform-badge ig">Instagram</div>
    <p>${esc(p.caption)}</p>
    ${(p.hashtags || []).length ? `<div class="hashtags">${esc((p.hashtags || []).join(' '))}</div>` : ''}
  </div>`).join('');
const pinHtml = (soc.pinterest || []).map(p => `
  <div class="social-post">
    <div class="platform-badge pin">Pinterest</div>
    <p><strong>${esc(p.title)}</strong></p>
    <p>${esc(p.description)}</p>
  </div>`).join('');
const fbHtml = (soc.facebook || []).map(p => `
  <div class="social-post">
    <div class="platform-badge fb">Facebook</div>
    <p>${esc(p.post)}</p>
  </div>`).join('');
const ttHtml = (soc.tiktok || []).map(p => `
  <div class="social-post">
    <div class="platform-badge tt">TikTok</div>
    <p><strong>Hook:</strong> ${esc(p.hook)}</p>
    <p>${esc(p.script)}</p>
  </div>`).join('');
const socialHtml = igHtml + pinHtml + fbHtml + ttHtml;

// ---------- Campaigns ----------
const camps = c.campaigns || [];
const campsHtml = camps.map(camp => {
  const det = camp.details || {};
  const detailsHtml = Object.entries(det).map(([k, v]) => `
    <div class="campaign-detail">
      <h5>${esc(k.replace(/_/g, ' ').replace(/\b\w/g, ch => ch.toUpperCase()))}</h5>
      <p>${esc(v)}</p>
    </div>`).join('');
  return `
  <div class="campaign-card">
    <h4>${esc(camp.name)}</h4>
    ${camp.tagline ? `<div class="tagline">&ldquo;${esc(camp.tagline)}&rdquo;</div>` : ''}
    <p>${esc(camp.description)}</p>
    ${detailsHtml ? `<div class="campaign-details">${detailsHtml}</div>` : ''}
  </div>`;
}).join('');

// ---------- Email subjects ----------
const emails = c.email_subjects || [];
const emailsHtml = emails.map(e => {
  const high = String(e.open_rate || '').toLowerCase() === 'high';
  return `
  <div class="email-subject">
    <span class="icon" aria-hidden="true">${esc(e.icon || '\u2709\uFE0F')}</span>
    <span class="subject-text">${esc(e.subject)}</span>
    <span class="open-rate ${high ? 'high' : 'medium'}">${high ? 'Higher' : 'Steady'} open potential</span>
  </div>`;
}).join('');

// ---------- Competitive angles ----------
const angles = c.competitive_angles || [];
const anglesHtml = angles.map(a => `
  <div class="competitive-angle">
    <h4>${esc(a.title)}</h4>
    <p><span class="tag gap">Where competitors leave room</span> ${esc(a.competitor_gap)}</p>
    <p><span class="tag opp">Where we can help</span> ${esc(a.wayfair_opportunity)}</p>
  </div>`).join('');

// ---------- Priorities ----------
const priorities = c.content_priorities || [];
const prioritiesHtml = priorities.map(p => `
  <div class="recommendation">
    <div class="priority ${Number(p.priority) <= 2 ? 'high' : 'medium'}">${esc(p.priority)}</div>
    <div class="recommendation-content">
      <h4>${esc(p.title)}</h4>
      <p>${esc(p.rationale)}</p>
    </div>
  </div>`).join('');

// ---------- Data-quality banner ----------
let banner = '';
if (status && status.ok === false && (status.missing || []).length) {
  banner = `<div class="banner warn">
    <strong>A heads-up before you read on.</strong>
    We couldn't read the following upload${status.missing.length > 1 ? 's' : ''}: ${esc(status.missing.join(', '))}.
    The strategy below is built only on what came through, so treat it as directional.
    Re-uploading the HTML report${status.missing.length > 1 ? 's' : ''} and re-running will give you a fuller picture.
  </div>`;
}
if (incomplete.length) {
  banner += `<div class="banner info">
    <strong>Partial run.</strong> ${esc(incomplete.join(', '))} came back empty this time.
    Everything else on this page is complete, and a re-run will usually fill the gap.
  </div>`;
}

// ---------- Contents nav ----------
const navItems = [
  ['summary', 'Executive Summary', true],
  ['foundation', 'What the Data Shows', !!(p2List || p3List)],
  ['ideas', 'Content Ideas', has(ideas)],
  ['social', 'Social Captions', !!socialHtml],
  ['campaigns', 'Campaign Concepts', has(camps)],
  ['email', 'Email Subject Lines', has(emails)],
  ['angles', 'Competitive Angles', has(angles)],
  ['priorities', 'Where to Start', has(priorities)]
].filter(x => x[2]).map(x => `<a href="#${x[0]}">${esc(x[1])}</a>`).join('');

const html = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Content Strategy | Wayfair ${esc(category)}</title>
<style>
  :root {
    --brand: #7B2D8E;
    --brand-dark: #5E1A6E;
    --brand-light: #9B4DB8;
    --brand-tint: #F4ECF7;
    --ink: #2B2B33;
    --ink-soft: #5A5A66;
    --line: #E4E0E8;
    --bg: #F7F6F9;
    --card: #FFFFFF;
  }

  *, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }

  html, body { max-width: 100%; overflow-x: hidden; }

  body {
    font-family: 'Segoe UI', -apple-system, BlinkMacSystemFont, Roboto, Helvetica, Arial, sans-serif;
    line-height: 1.65;
    color: var(--ink);
    background: var(--bg);
    -webkit-font-smoothing: antialiased;
  }

  /* Long words, URLs and hashtag runs wrap instead of overflowing. */
  h1, h2, h3, h4, h5, p, li, td, th, span, div {
    overflow-wrap: anywhere;
    word-break: break-word;
  }

  img, svg, table, pre { max-width: 100%; height: auto; }
  pre { white-space: pre-wrap; }

  .container { max-width: 1080px; margin: 0 auto; padding: 24px 20px 48px; }

  /* ---------- Header ---------- */
  .header {
    background: linear-gradient(135deg, var(--brand) 0%, var(--brand-dark) 100%);
    color: #fff; padding: 40px 36px; border-radius: 14px; margin-bottom: 24px;
  }
  .header h1 { font-size: clamp(1.6rem, 4vw, 2.2rem); line-height: 1.25; margin-bottom: 8px; font-weight: 700; }
  .header .subtitle { font-size: clamp(1rem, 2.2vw, 1.15rem); opacity: .92; }
  .header .meta { margin-top: 20px; display: flex; gap: 10px; flex-wrap: wrap; }
  .header .meta-item {
    background: rgba(255,255,255,.16); padding: 7px 14px; border-radius: 999px;
    font-size: .85rem; white-space: nowrap;
  }

  /* ---------- Banners ---------- */
  .banner { border-radius: 10px; padding: 16px 20px; margin-bottom: 18px; font-size: .95rem; line-height: 1.6; }
  .banner.warn { background: #FEF6E7; border-left: 4px solid #E0A800; color: #6B4E00; }
  .banner.info { background: var(--brand-tint); border-left: 4px solid var(--brand); color: var(--brand-dark); }

  /* ---------- Contents nav ---------- */
  .report-nav {
    background: var(--card); border-radius: 12px; padding: 18px 22px; margin-bottom: 24px;
    box-shadow: 0 1px 4px rgba(0,0,0,.06); display: flex; flex-wrap: wrap; gap: 8px 14px; align-items: center;
  }
  .report-nav .nav-label { font-size: .78rem; text-transform: uppercase; letter-spacing: .08em; color: var(--ink-soft); width: 100%; }
  .report-nav a { color: var(--brand); text-decoration: none; font-size: .9rem; font-weight: 500; padding: 4px 10px; border-radius: 999px; background: var(--brand-tint); }
  .report-nav a:hover { background: var(--brand); color: #fff; }

  /* ---------- Sections ---------- */
  .section {
    background: var(--card); border-radius: 12px; padding: 30px 28px; margin-bottom: 22px;
    box-shadow: 0 1px 4px rgba(0,0,0,.06); scroll-margin-top: 20px;
  }
  .section h2 {
    color: var(--brand); font-size: 1.35rem; margin-bottom: 6px;
    padding-bottom: 10px; border-bottom: 2px solid var(--brand-tint);
  }
  .section .lede { color: var(--ink-soft); margin: 12px 0 22px; font-size: .98rem; }
  .empty-note {
    background: var(--bg); border: 1px dashed var(--line); border-radius: 8px;
    padding: 16px 18px; color: var(--ink-soft); font-size: .93rem;
  }

  /* ---------- Executive summary ---------- */
  .exec-summary { border-left: 4px solid var(--brand); }
  .exec-summary .summary-text { font-size: 1.02rem; white-space: pre-line; margin-bottom: 24px; }

  /* Grid fix: minmax(0,...) lets tracks shrink; min-width:0 on children
     stops one long word from forcing the whole card past its container. */
  .key-insights {
    display: grid; gap: 14px; margin-top: 8px;
    grid-template-columns: repeat(auto-fit, minmax(min(100%, 170px), 1fr));
  }
  .key-insights > * { min-width: 0; }
  .insight-card {
    background: var(--brand-tint); border: 1px solid var(--line); border-radius: 10px;
    padding: 18px 14px; text-align: center;
  }
  .insight-card .number { font-size: clamp(1.4rem, 3.4vw, 2rem); font-weight: 700; color: var(--brand); line-height: 1.2; }
  .insight-card .label { font-size: .82rem; color: var(--ink-soft); margin-top: 6px; }
  .insight-card .src { font-size: .7rem; color: var(--ink-soft); opacity: .75; margin-top: 4px; }

  /* ---------- Data foundation ---------- */
  .data-sources { display: grid; gap: 18px; grid-template-columns: repeat(auto-fit, minmax(min(100%, 300px), 1fr)); }
  .data-sources > * { min-width: 0; }
  .data-source-card { background: var(--bg); border-radius: 10px; padding: 20px; }
  .data-source-card h4 { color: var(--brand); margin-bottom: 10px; font-size: 1rem; }
  .data-source-card ul { list-style: none; }
  .data-source-card li { padding: 9px 0; border-bottom: 1px solid var(--line); font-size: .94rem; }
  .data-source-card li:last-child { border-bottom: none; }

  /* ---------- Content ideas ---------- */
  .content-grid { display: grid; gap: 18px; grid-template-columns: repeat(auto-fit, minmax(min(100%, 300px), 1fr)); }
  .content-grid > * { min-width: 0; }
  .content-card {
    background: var(--card); border: 1px solid var(--line); border-radius: 10px;
    display: flex; flex-direction: column; overflow: hidden;
  }
  .content-card-header { background: linear-gradient(135deg, var(--brand) 0%, var(--brand-light) 100%); color: #fff; padding: 15px 18px; }
  .content-card-header .type { font-size: .7rem; text-transform: uppercase; letter-spacing: .1em; opacity: .9; }
  .content-card-header h4 { font-size: 1.05rem; margin-top: 5px; line-height: 1.35; }
  .content-card-body { padding: 18px; flex: 1 1 auto; min-width: 0; }
  .content-card-body p { color: var(--ink-soft); margin-bottom: 14px; font-size: .94rem; }
  .data-tag {
    display: block; background: var(--brand-tint); color: var(--brand-dark);
    padding: 8px 12px; border-radius: 8px; font-size: .82rem; line-height: 1.5;
  }
  .keywords { margin-top: 12px; display: flex; flex-wrap: wrap; gap: 6px; }
  .keyword { background: var(--bg); border: 1px solid var(--line); color: var(--ink-soft); padding: 4px 10px; border-radius: 999px; font-size: .78rem; }

  /* ---------- Social ---------- */
  .social-grid { display: grid; gap: 14px; grid-template-columns: repeat(auto-fit, minmax(min(100%, 270px), 1fr)); }
  .social-grid > * { min-width: 0; }
  .social-post { background: var(--bg); border-radius: 10px; padding: 16px; }
  .platform-badge { display: inline-block; padding: 4px 10px; border-radius: 999px; font-size: .72rem; font-weight: 600; color: #fff; margin-bottom: 10px; }
  .platform-badge.ig { background: linear-gradient(45deg, #F09433, #DC2743); }
  .platform-badge.pin { background: #E60023; }
  .platform-badge.fb { background: #1877F2; }
  .platform-badge.tt { background: #111; }
  .social-post p { font-size: .93rem; margin-bottom: 8px; }
  .hashtags { color: var(--brand); font-size: .84rem; }

  /* ---------- Campaigns ---------- */
  .campaign-card { background: var(--bg); border: 1px solid var(--line); border-radius: 10px; padding: 24px; margin-bottom: 18px; }
  .campaign-card h4 { color: var(--brand-dark); font-size: 1.2rem; margin-bottom: 6px; }
  .campaign-card .tagline { color: var(--brand); font-style: italic; font-size: 1.02rem; margin-bottom: 14px; }
  .campaign-card > p { margin-bottom: 18px; font-size: .96rem; }
  .campaign-details { display: grid; gap: 14px; grid-template-columns: repeat(auto-fit, minmax(min(100%, 210px), 1fr)); }
  .campaign-details > * { min-width: 0; }
  .campaign-detail { background: var(--card); padding: 14px 16px; border-radius: 8px; border: 1px solid var(--line); }
  .campaign-detail h5 { color: var(--brand); font-size: .82rem; text-transform: uppercase; letter-spacing: .05em; margin-bottom: 7px; }
  .campaign-detail p { font-size: .89rem; color: var(--ink-soft); }

  /* ---------- Email subjects ---------- */
  /* flex-wrap + min-width:0 stops long subjects pushing the badge off-screen */
  .email-ideas { display: flex; flex-direction: column; gap: 10px; }
  .email-subject {
    display: flex; align-items: center; flex-wrap: wrap; gap: 10px 14px;
    background: var(--bg); padding: 14px 18px; border-radius: 10px;
  }
  .email-subject .icon { font-size: 1.25rem; flex-shrink: 0; }
  .email-subject .subject-text { flex: 1 1 240px; min-width: 0; font-size: .97rem; }
  .email-subject .open-rate {
    flex-shrink: 0; background: #E4F3EA; color: #14724A;
    padding: 5px 12px; border-radius: 999px; font-size: .76rem; font-weight: 600; white-space: nowrap;
  }
  .email-subject .open-rate.medium { background: #FDF2D8; color: #8A5A00; }

  /* ---------- Competitive angles ---------- */
  .competitive-angle { background: var(--bg); border-left: 4px solid var(--brand); padding: 20px; margin-bottom: 14px; border-radius: 0 10px 10px 0; }
  .competitive-angle h4 { color: var(--brand-dark); margin-bottom: 12px; font-size: 1.05rem; }
  .competitive-angle p { margin-bottom: 10px; font-size: .94rem; }
  .tag { display: inline-block; font-size: .72rem; font-weight: 600; text-transform: uppercase; letter-spacing: .05em; padding: 3px 9px; border-radius: 999px; margin-right: 6px; }
  .tag.gap { background: #FDF2D8; color: #8A5A00; }
  .tag.opp { background: var(--brand-tint); color: var(--brand-dark); }

  /* ---------- Priorities ---------- */
  .recommendation { display: flex; gap: 16px; margin-bottom: 14px; align-items: flex-start; }
  .priority {
    width: 40px; height: 40px; border-radius: 50%; display: flex; align-items: center; justify-content: center;
    font-weight: 700; font-size: 1.1rem; color: #fff; flex-shrink: 0;
  }
  .priority.high { background: var(--brand); }
  .priority.medium { background: var(--brand-light); }
  .recommendation-content { flex: 1 1 auto; min-width: 0; background: var(--bg); padding: 16px 20px; border-radius: 10px; }
  .recommendation-content h4 { color: var(--brand-dark); margin-bottom: 7px; font-size: 1.02rem; }
  .recommendation-content p { font-size: .94rem; color: var(--ink-soft); }

  /* ---------- Footer ---------- */
  .footer { background: var(--brand-dark); color: #fff; padding: 28px; border-radius: 12px; text-align: center; margin-top: 26px; }
  .footer .logo { font-size: 1.1rem; font-weight: 700; margin-bottom: 8px; }
  .footer p { opacity: .88; font-size: .86rem; margin-top: 5px; }

  /* ============ PRINT / SAVE AS PDF ============ */
  @page { size: A4; margin: 14mm 12mm; }

  @media print {
    body { background: #fff; font-size: 10.5pt; }
    .container { max-width: none; padding: 0; }
    .report-nav { display: none; }

    .section, .content-card, .campaign-card, .social-post, .recommendation,
    .competitive-angle, .insight-card, .email-subject, .data-source-card,
    .campaign-detail, .header, .footer, .banner {
      break-inside: avoid; page-break-inside: avoid; box-shadow: none;
    }
    h1, h2, h3, h4 { break-after: avoid; page-break-after: avoid; }
    .section { border: 1px solid var(--line); }
    * { -webkit-print-color-adjust: exact !important; print-color-adjust: exact !important; }
  }

  /* ============ SMALL SCREENS ============ */
  @media (max-width: 640px) {
    .container { padding: 14px 12px 32px; }
    .header { padding: 26px 20px; }
    .section { padding: 22px 16px; }
    .recommendation { gap: 12px; }
  }
</style>
</head>
<body>
<div class="container">

  <header class="header">
