  </section>` : ''}

  ${has(priorities) ? `
  <section class="section" id="priorities">
    <h2>Where to Start</h2>
    <p class="lede">If you only have bandwidth for a few things, this is the order we'd suggest, and the reasoning behind it. Adjust freely for what you know about your team and calendar.</p>
    ${prioritiesHtml}
  </section>` : ''}

  <footer class="footer">
    <div class="logo">Wayfair &middot; AI Insights &amp; Content Agent</div>
    <p>Built from your Market Trend Discovery and Competitor Monitoring reports.</p>
    <p>${esc(category)}${focus ? ' &middot; ' + esc(focus) : ''} &middot; ${esc(today)}</p>
  </footer>

</div>
</body>
</html>`;

return [{ json: { html, category, focus } }];

const html = $input.first().json.html;
const cat = $input.first().json.category || 'Area Rug';
const ts = new Date().toISOString().split('T')[0];
const fileName = `Wayfair_${cat.replace(/\s+/g, '_')}_Content_Strategy_${ts}.html`;

return [{
  json: { html, fileName },
  binary: {
    data: {
      data: Buffer.from(html).toString('base64'),
      mimeType: 'text/html',
      fileName: fileName
    }
  }
}];
